17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
31	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.Region;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
41	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
42	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
43	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
44	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
45	import org.springframework.samples.petclinic.rest.api.OwnersApi;
46	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
47	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.PetDto;
49	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
52	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
53	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
54	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
55	import org.springframework.samples.petclinic.service.ClinicService;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
77	    private static final int MAX_OWNERS_PER_CITY = 50;
78	
79	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
80	    private static final int MAX_OWNERS_PER_DAY = 100;
81	
82	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
83	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    private final TelephoneNormalizer telephoneNormalizer;
94	
95	    private final AddressNormalizer addressNormalizer;
96	
97	    private final EmailNormalizer emailNormalizer;
98	
99	    private final IdentityKeyResolver identityKeyResolver;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper,
105	                                 TelephoneNormalizer telephoneNormalizer,
106	                                 AddressNormalizer addressNormalizer,
107	                                 EmailNormalizer emailNormalizer,
108	                                 IdentityKeyResolver identityKeyResolver) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	        this.telephoneNormalizer = telephoneNormalizer;
114	        this.addressNormalizer = addressNormalizer;
115	        this.emailNormalizer = emailNormalizer;
116	        this.identityKeyResolver = identityKeyResolver;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        owners.forEach(this::populateHouseholdMemberCount);
132	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
133	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        populateHouseholdMemberCount(owner);
144	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    /**
148	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
149	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
150	     * by the mapper alone.
151	     *
152	     * @param owner the owner to map
153	     * @return the owner DTO carrying its identity key
154	     */
155	    private OwnerDto toOwnerDto(Owner owner) {
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
158	        return ownerDto;
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
165	        normalizeAndValidate(ownerFieldsDto);
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        populateDerivedFields(owner, ownerFieldsDto);
169	        requireUniqueIdentity(owner);
170	        flagPossibleDuplicate(owner);
171	        this.clinicService.saveOwner(owner);
172	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
173	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
174	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
175	        populateHouseholdMemberCount(owner);
176	        OwnerDto ownerDto = toOwnerDto(owner);
177	        headers.setLocation(UriComponentsBuilder.newInstance()
178	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
179	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
180	    }
181	
182	    /**
183	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
184	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
185	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
186	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
187	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
188	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), backfilling any existing household members
189	     * that lack it, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The owner is
190	     * mutated in place; the caller applies the duplicate guard and saves it.
191	     *
192	     * @param owner          the newly mapped owner about to be saved
193	     * @param ownerFieldsDto the incoming owner payload
194	     */
195	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
196	        owner.setCustomerCode(identityKeyResolver.deriveCustomerCode(owner));
197	        owner.setNamesakeCount(countNamesakes(owner));
198	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
199	        assignHouseholdId(owner, ownerFieldsDto);
200	    }
201	
202	    /**
203	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
204	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
205	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
206	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
207	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
208	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
209	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
210	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
211	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
212	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
213	     * assigned (see {@link #requireUniqueIdentity}).
214	     *
215	     * @param ownerFieldsDto the incoming owner payload, mutated in place
216	     * @throws MissingOwnerFieldsException if any required field is missing or blank
217	     */
218	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
219	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
220	        validateRequiredFields(ownerFieldsDto);
221	        validatePostcode(ownerFieldsDto);
222	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
223	        ownerFieldsDto.setTelephone(telephone);
224	        requireCityHasCapacity(ownerFieldsDto.getCity());
225	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
226	        ownerFieldsDto.setRegistrationDate(registrationDate);
227	        requireDailyLimitNotReached(registrationDate);
228	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
229	        ownerFieldsDto.setEmail(email);
230	    }
231	
232	    /**
233	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
234	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
235	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
236	     * later than the current server date is rejected.
237	     *
238	     * @param ownerFieldsDto the incoming owner payload
239	     * @return the effective registration date rolled forward onto a business day
240	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
241	     */
242	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
243	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
244	        if (effective == null) {
245	            effective = LocalDate.now();
246	        }
247	        else if (effective.isAfter(LocalDate.now())) {
248	            throw new FutureRegistrationDateException(
249	                "the registration date must not be later than the current server date");
250	        }
251	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
252	            effective = effective.plusDays(1);
253	        }
254	        return effective;
255	    }
256	
257	    /**
258	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
259	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
260	     * further owner may be created for that day.
261	     *
262	     * @param registrationDate the adjusted business-day registration date of the owner being created
263	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
264	     */
265	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
266	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
267	            throw new DailyOwnerLimitExceededException(
268	                "the maximum number of owners for today has already been reached");
269	        }
270	    }
271	
272	    /**
273	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
274	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
275	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
276	     * warning threshold) so both express the same per-day count in one place.
277	     *
278	     * @param registrationDate the adjusted business-day registration date to count owners for
279	     * @return the number of existing owners registered on that day
280	     */
281	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
282	        return this.clinicService.findAllOwners().stream()
283	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
284	            .count();
285	    }
286	
287	    /**
288	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
289	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
290	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
291	     * reflects only owners that predate it.
292	     *
293	     * @param registrationDate the adjusted business-day registration date of the owner being created
294	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
295	     */
296	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
297	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
298	    }
299	
300	    /**
301	     * Counts how many existing owners already share the given owner's first and last name, compared
302	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
303	     * create; it is zero when the owner's name is unique.
304	     *
305	     * @param owner the newly mapped owner about to be saved
306	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
307	     */
308	    private int countNamesakes(Owner owner) {
309	        String firstName = owner.getFirstName();
310	        String lastName = owner.getLastName();
311	        return (int) this.clinicService.findAllOwners().stream()
312	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
313	                && lastName.equalsIgnoreCase(existing.getLastName()))
314	            .count();
315	    }
316	
317	    /**
318	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
319	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
320	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
321	     *
322	     * @param ownerFieldsDto the owner payload to validate
323	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
324	     */
325	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
326	        List<String> missingFields = new ArrayList<>();
327	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
328	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
329	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
330	        requireText(missingFields, "city", ownerFieldsDto.getCity());
331	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
332	        if (!missingFields.isEmpty()) {
333	            throw new MissingOwnerFieldsException(missingFields);
334	        }
335	    }
336	
337	    private void requireText(List<String> missingFields, String fieldName, String value) {
338	        if (value == null || value.isBlank()) {
339	            missingFields.add(fieldName);
340	        }
341	    }
342	
343	    /**
344	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
345	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
346	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
347	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
348	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
349	     *
350	     * @param ownerFieldsDto the incoming owner payload
351	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
352	     */
353	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
354	        String postcode = ownerFieldsDto.getPostcode();
355	        if (postcode == null) {
356	            return;
357	        }
358	        Region region = Region.forCity(ownerFieldsDto.getCity());
359	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
360	            throw new InvalidPostcodeException(
361	                "postcode " + postcode + " is not valid for the city's region " + region.name());
362	        }
363	    }
364	
365	    /**
366	     * Rejects creating an owner whose whole derived {@code identityKey} (see
367	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner. This is the single, consolidated
368	     * duplicate check: the former separate telephone, email and household rules are all expressed through this one key,
369	     * so an owner is a duplicate only when its normalized telephone, email and {@code householdId} all match another
370	     * owner's. It runs after the household id has been assigned, so the key reflects the household the owner belongs to.
371	     *
372	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
373	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
374	     */
375	    private void requireUniqueIdentity(Owner owner) {
376	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
377	        boolean inUse = this.clinicService.findAllOwners().stream()
378	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
379	        if (inUse) {
380	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
381	        }
382	    }
383	
384	    /**
385	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
386	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. It is a
387	     * possible duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode
388	     * but carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true}
389	     * and {@code possibleDuplicateOf} to that existing owner's id (the first match in
390	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
391	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
392	     *
393	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
394	     */
395	    private void flagPossibleDuplicate(Owner owner) {
396	        owner.setPossibleDuplicate(false);
397	        String postcode = owner.getPostcode();
398	        if (postcode == null || postcode.isBlank()) {
399	            return;
400	        }
401	        String lastName = owner.getLastName();
402	        String telephone = owner.getTelephone();
403	        for (Owner existing : this.clinicService.findAllOwners()) {
404	            if (lastName.equalsIgnoreCase(existing.getLastName())
405	                && postcode.equals(existing.getPostcode())
406	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
407	                owner.setPossibleDuplicate(true);
408	                owner.setPossibleDuplicateOf(existing.getId());
409	                return;
410	            }
411	        }
412	    }
413	
414	    /**
415	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
416	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
417	     *
418	     * @param city the city of the owner being created
419	     * @throws OwnerCityFullException if the city already contains 50 or more owners
420	     */
421	    private void requireCityHasCapacity(String city) {
422	        long cityOwners = this.clinicService.findAllOwners().stream()
423	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
424	            .count();
425	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
426	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
427	        }
428	    }
429	
430	    /**
431	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
432	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
433	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
434	     * incidental formatting differences and abbreviation variants do not affect membership.
435	     *
436	     * @param ownerFieldsDto the incoming owner payload
437	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
438	     *         them; empty when none match
439	     */
440	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
441	        String lastName = identityKeyResolver.collapseWhitespace(ownerFieldsDto.getLastName());
442	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
443	        return this.clinicService.findAllOwners().stream()
444	            .filter(existing -> identityKeyResolver.collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
445	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
446	            .toList();
447	    }
448	
449	    /**
450	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
451	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
452	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
453	     * identifier is derived deterministically from the household's last name and address (see
454	     * {@link IdentityKeyResolver#deriveHouseholdId}), so every member of the same household resolves to the same stable
455	     * value regardless of creation order. Existing members that predate the feature and still lack the identifier are
456	     * backfilled (see {@link #backfillHouseholdMembers}) so the whole household shares it.
457	     *
458	     * @param owner          the newly mapped owner about to be saved
459	     * @param ownerFieldsDto the incoming owner payload
460	     */
461	    private void assignHouseholdId(Owner owner, OwnerFieldsDto ownerFieldsDto) {
462	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
463	            return;
464	        }
465	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
466	        if (members.isEmpty()) {
467	            return;
468	        }
469	        String householdId =
470	            identityKeyResolver.deriveHouseholdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
471	        owner.setHouseholdId(householdId);
472	        backfillHouseholdMembers(householdId, members);
473	    }
474	
475	    /**
476	     * Stamps the shared {@code householdId} onto the existing members of a household that do not already carry it,
477	     * persisting each one that changes. Members that predate the feature (and so still lack the identifier) are brought
478	     * into line so the whole household shares the single value; members that already carry it are left untouched.
479	     *
480	     * @param householdId the shared household identifier
481	     * @param members     the existing owners in the household
482	     */
483	    private void backfillHouseholdMembers(String householdId, List<Owner> members) {
484	        for (Owner member : members) {
485	            if (!householdId.equals(member.getHouseholdId())) {
486	                member.setHouseholdId(householdId);
487	                this.clinicService.saveOwner(member);
488	            }
489	        }
490	    }
491	
492	    /**
493	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
494	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
495	     * household is counted as a household of one.
496	     *
497	     * @param owner the owner whose household size should be resolved
498	     */
499	    private void populateHouseholdMemberCount(Owner owner) {
500	        String householdId = owner.getHouseholdId();
501	        if (householdId == null) {
502	            owner.setHouseholdMemberCount(1);
503	            return;
504	        }
505	        long members = this.clinicService.findAllOwners().stream()
506	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
507	            .count();
508	        owner.setHouseholdMemberCount((int) members);
509	    }
510	
511	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
512	    @Override
513	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
514	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
515	        if (currentOwner == null) {
516	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
517	        }
518	        validatePostcode(ownerFieldsDto);
519	        currentOwner.setAddress(ownerFieldsDto.getAddress());
520	        currentOwner.setCity(ownerFieldsDto.getCity());
521	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
522	        currentOwner.setLastName(ownerFieldsDto.getLastName());
523	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
524	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
525	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
526	        this.clinicService.saveOwner(currentOwner);
527	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
528	    }
529	
530	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
531	    @Transactional
532	    @Override
533	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
534	        Owner owner = this.clinicService.findOwnerById(ownerId);
535	        if (owner == null) {
536	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
537	        }
538	        this.clinicService.deleteOwner(owner);
539	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
540	    }
541	
542	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
543	    @Override
544	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
545	        Owner owner = this.clinicService.findOwnerById(ownerId);
546	        if (owner == null) {
547	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
548	        }
549	        HttpHeaders headers = new HttpHeaders();
550	        Pet pet = petMapper.toPet(petFieldsDto);
551	        owner.setId(ownerId);
552	        pet.setOwner(owner);
553	        pet.getType().setName(null);
554	        this.clinicService.savePet(pet);
555	        PetDto petDto = petMapper.toPetDto(pet);
556	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
557	            .buildAndExpand(pet.getId()).toUri());
558	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
559	    }
560	
561	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
562	    @Override
563	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
564	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
565	        if (currentOwner != null) {
566	            Pet currentPet = this.clinicService.findPetById(petId);
567	            if (currentPet != null) {
568	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
569	                currentPet.setName(petFieldsDto.getName());
570	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
571	                this.clinicService.savePet(currentPet);
572	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
573	            }
574	        }
575	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
576	    }
577	
578	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
579	    @Override
580	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
581	        HttpHeaders headers = new HttpHeaders();
582	        Visit visit = visitMapper.toVisit(visitFieldsDto);
583	        Pet pet = new Pet();
584	        pet.setId(petId);
585	        visit.setPet(pet);
586	        this.clinicService.saveVisit(visit);
587	        VisitDto visitDto = visitMapper.toVisitDto(visit);
588	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
589	            .buildAndExpand(visit.getId()).toUri());
590	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
591	    }
592	
593	
594	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
595	    @Override
596	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
597	        Owner owner = this.clinicService.findOwnerById(ownerId);
598	        if (owner != null) {
599	            Pet pet = owner.getPet(petId);
600	            if (pet != null) {
601	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
602	            }
603	        }
604	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
605	    }
606	}
